-- =============================================================================
-- NOONA PLUS ERP | كتالوج مركز التقارير الموحد (TENANT_ID = NULL) - مولد من tools/bi_catalog.py (لا تعدله يدوياً)
--   كل تقرير: الوحدة، التطبيق والصفحة، رمز التقرير داخل مركز تقارير الوحدة، والصلاحية المطلوبة
--   التقارير التي حذفت من الكتالوج تصبح RETIRED ولا تظهر
-- =============================================================================
SET DEFINE OFF
BEGIN
  NOONA_CORE_PKG.begin_system;
  MERGE INTO bi_report r
  USING (SELECT 'GL_TB' code, 'GL' module_code, 'FINANCIAL' report_type, 'NOONA_FIN' app_alias, 'TRIAL-BALANCE' page_alias, NULL page_no, NULL param_item, NULL param_value, 'GL_JOURNAL.VIEW' permission_code, 'fa-balance-scale' icon_class, 'ميزان المراجعة' name_ar, 'Trial balance' name_en, 'أرصدة الحسابات الافتتاحية والحركة والختامية لفترة، بمستويات الدليل ومركز التكلفة' dsc, 10 sort_order FROM dual
         UNION ALL SELECT 'GL_STMT', 'GL', 'FINANCIAL', 'NOONA_FIN', 'STATEMENT', 31, NULL, NULL, 'GL_JOURNAL.VIEW', 'fa-file-text-o', 'كشف حساب', 'Account statement', 'حركة حساب بالتفصيل والرصيد التراكمي مع الوصول للقيد ومستند المصدر', 20 FROM dual
