         UNION ALL SELECT 'GL_EQ', 'GL', 'FINANCIAL', 'NOONA_FIN', 'EQUITY-CHANGES', NULL, NULL, NULL, 'GL_JOURNAL.VIEW', 'fa-pie-chart', 'التغيرات في حقوق الملكية', 'Changes in equity', 'حركة رأس المال والاحتياطيات والأرباح المبقاة', 60 FROM dual
