         UNION ALL SELECT 'FA_ROLL', 'FA', 'FINANCIAL', 'NOONA_FIN', 'ASSET-REPORTS', 66, 'P66_REPORT', 'ROLL', 'FA_ASSET.VIEW', 'fa-refresh', 'حركة الأصول ومطابقة الأستاذ', 'Asset roll-forward', 'الرصيد الافتتاحي والإضافات والاستبعادات والإهلاك ومطابقتها مع حسابات الأستاذ', 170 FROM dual
