   WHERE tenant_id IS NULL AND app_alias IS NOT NULL AND status_code = 'PUBLISHED'
     AND code NOT IN ('GL_TB', 'GL_STMT', 'GL_IS', 'GL_BS', 'GL_CF', 'GL_EQ', 'GL_CMP', 'GL_RATIOS', 'GL_ANALYSIS', 'GL_LEDGER', 'GL_JREG', 'GL_JTYPE', 'GL_CONTROLS', 'GL_AUDIT', 'CSH_BOOK', 'FA_REGISTER', 'FA_ROLL', 'FA_DISPOSALS', 'FA_DISPOSED', 'TAX_REGISTER', 'TAX_RETURNS', 'TAX_WHT', 'TAX_EINV', 'INV_STOCK', 'INV_CARD', 'INV_EXPIRY', 'INV_REORDER', 'INV_FIT', 'PUR_REG', 'PUR_ITEM', 'PUR_STMT', 'PUR_AGING', 'SAL_REG', 'SAL_ITEM', 'SAL_POS', 'SAL_STMT', 'SAL_AGING', 'RST_DASH', 'HR_HEADCOUNT', 'HR_LEAVES', 'HR_ATTENDANCE', 'HR_EXPIRING', 'PAY_REGISTER', 'PAY_ELEMENTS', 'PAY_GOSI', 'PAY_CC', 'PAY_EOS', 'PAY_LOANS', 'RE_AVAILABILITY', 'RE_COLLECTIONS', 'RE_SALES', 'PRP_RENT_ROLL', 'PRP_LEASING', 'PRP_OWNERS', 'HSP_INHOUSE', 'HSP_OCC', 'HSP_ARRIVALS', 'HSP_CITY', 'PRJ_PORTFOLIO', 'PRJ_CLAIMS', 'PRJ_RETENTION', 'PRJ_COSTS', 'PRJ_UNITS', 'MNT_PERF', 'MFG_ORDERS', 'MFG_WIP', 'MFG_VAR', 'MFG_USAGE', 'MFG_SUMMARY', 'MFG_UTIL', 'MFG_LOAD', 'MFG_TREE', 'MFG_USED', 'MFG_MRP', 'MFG_QC', 'HIS_REV', 'HIS_CLAIM', 'HIS_CLAIMS', 'HIS_COMM', 'DMS_EXPIRING', 'DMS_ACCESS');
  NOONA_CORE_PKG.end_system;
  COMMIT;
EXCEPTION WHEN OTHERS THEN
  NOONA_CORE_PKG.end_system;
  ROLLBACK;
  RAISE;
END;
